// Turns the renderer's structured stats into a plain-English prompt so Claude can write the
// actual daily report -- the numbers themselves come only from the renderer's analysis, never
// from the model, so a bad Claude response can only produce bad prose, never a bad weight.
const report = $json;
function pct(x) { return `${(Number(x) * 100).toFixed(1)}%`; }
function label(arm) { return arm ? `${arm.slug} (${arm.format})` : 'unknown'; }

let summary;
if (!report.weightsChanged) {
  summary = `Not enough data yet to compare topics today (reason: ${report.skipReason}). Weights are unchanged from before.`;
} else {
  const lines = (report.leaderboard || []).map((arm, index) => `${index + 1}. ${label(arm)} -- engagement rate ${pct(arm.avgEngagementRate)} across ${arm.sampleCount} post(s) this window, weight ${pct(arm.previousWeight)} -> ${pct(arm.weight)}`).join('\n');
  summary = `Top performer: ${label(report.topPerformer)} (engagement rate ${pct(report.topPerformer?.avgEngagementRate)}).\nBottom performer: ${label(report.bottomPerformer)} (engagement rate ${pct(report.bottomPerformer?.avgEngagementRate)}).\n\nFull ranking:\n${lines}`;
}
const untouched = (report.arms || []).filter((arm) => arm.sampleCount === 0).map(label).join(', ');

const prompt = `Write a short, plain-English daily report (4-8 sentences) for ${report.date} about an Instagram Reels topic-distribution experiment. Five developer-content topics, each published in a "Tips" and "Trend" format (10 arms total), are dispatched with probability proportional to a weight that shifts toward whichever arm gets real Instagram engagement (likes+comments+shares+saves divided by reach), recomputed once per day.\n\n${summary}\n\n${untouched ? `No fresh posts yet this window for: ${untouched}.\n\n` : ''}Explain plainly which topic did statistically well today and how the weight distribution is moving as a result of that. No headers, no bullet points, no markdown -- just clear prose a busy person can skim in ten seconds. Do not invent any number not given above.`;

return [{json: {prompt, report}}];

// Claude only writes the sentence; if the call fails or returns something unusable, this falls
// back to a deterministic one-line summary built straight from the structured report so a report
// is always produced (it just reads less naturally without Claude's help).
const context = $items('Build Narrative Prompt')[0]?.json ?? {};
const report = context.report ?? {};
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content)
  ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim()
  : '';

let narrative;
let narrativeSource = 'fallback';
if (statusCode >= 200 && statusCode < 300 && text) {
  narrative = text;
  narrativeSource = 'claude';
}
if (!narrative) {
  narrative = report.weightsChanged
    ? `Top performer: ${report.topPerformer?.slug} (${report.topPerformer?.format}). Bottom performer: ${report.bottomPerformer?.slug} (${report.bottomPerformer?.format}). Weights updated for ${report.date}.`
    : `Not enough data yet to compare topics as of ${report.date} (${report.skipReason ?? 'insufficient samples'}). Weights unchanged.`;
}
return [{json: {date: report.date, narrative, narrativeSource}}];
